/** A root folder holding modules and repositories, with one project manifest (<root>/.compose/compose.json `project`). Id: <project>:Project:<key>, key = project.name (lowercase slug). Id = <name>:Project:<name>. */
export interface Project {
  name: string;
  label?: string;
}

/** A virtual label over a project's modules and repositories; no store of its own. Id: <project>:Group:<key>, key = group name from project.groups, lowercased, spaces to '-'. */
export interface Group {
  name: string;
}

/** A sub-folder of a project with its own roadmap and feature store. Id: <project>:Module:<key>, key = project.modules[].name; path holds the realpath (one realpath = one module, project-model.js:11-12). */
export interface Module {
  name: string;
  path?: string;
}

/** A git repository checked out inside a project. Id: <project>:Repository:<key>, key = checkout path relative to the project root. Worktrees are not repositories. */
export interface Repository {
  name: string;
  path?: string;
}

/** A published version of a module or repository. Id: <project>:Release:<key>, key = <module or repository key>@<version>. */
export interface Release {
  version: string;
  released_at?: string;
}

/** A roadmap item with a feature code, owned by exactly one module. Id: <project>:Feature:<key>, key = feature code (^[A-Z][A-Z0-9-]*[A-Z0-9]$), unique within a project. */
export interface Feature {
  code: string;
  description?: string;
  status?: string;
  phase?: string;
}

/** A bounded, dispatched piece of work with a brief and a report. Id: <project>:Unit:<key>, key = unit folder name under smart-memory-ops/units/. Project segment = the dispatching lane's project, fallback smartmemory. */
export interface Unit {
  id: string;
  repos?: string[];
}

/** A standing stream of work in a project, run by one long-lived session. Id: <project>:Lane:<key>, key = project.lanes[].id. */
export interface Lane {
  id: string;
  label?: string;
  ops_lane?: string;
  repo?: string;
  module?: string;
}

/** A model-provider account sessions run on, with its own quota. Id: <project>:Seat:<key>, key = seat<N>; global: _:Seat:seat<N>. Names only, never credentials. */
export interface Seat {
  id: string;
}

/** One running agent session with a role name, on one seat at a time. Id: <project>:Session:<key>, key = session UUID; global: _:Session:<uuid>. The role name is a property (reused across restarts). */
export interface Session {
  session_id: string;
  name?: string;
}

/** A checkpoint a unit or feature must pass: a review round or a Compose lifecycle gate. Id: <project>:Gate:<key>, key = <unit or feature>:r<round>:<reviewer>, or <feature>:<phase> for lifecycle gates. Ids split on the first two ':' only. */
export interface Gate {
  id: string;
  round: number;
  verdict?: string;
  tier?: string;
}

/** A recorded project decision: an owner decision (D-NNNN) or a lane-lead ruling. Id: <project>:ProjectDecision:<key>, key = D-NNNN for owner decisions; <lane>-ruling-<sha12> for rulings. */
export interface ProjectDecision {
  id: string;
  statement?: string;
  owner_quote?: string;
}

/** A raw product idea not yet on a roadmap, with an attention level. Id: <project>:Idea:<key>, key = ideabox id. */
export interface Idea {
  id: string;
  title?: string;
  attention?: string;
}

/** A git commit in a repository. Id: <project>:Commit:<key>, key = <repository key>@<sha40>. The repository is a property, not an edge. */
export interface Commit {
  sha: string;
  repo: string;
}

/** A file produced or used by work: brief, report, review, design, plan, contract. Id: <project>:Artifact:<key>, key = <repository key>/<path in repository>. */
export interface Artifact {
  path: string;
}
